#!/usr/bin/env node
/* biome-ignore-all lint/suspicious/noConsole: CLI entry point */
// The `vercel` bin (dist/vc.js in the vercel package, built from this file).
// It runs the native binary, or the JS CLI from @vercel/cli-support
// (src/vc.js, its dist/vc.js), and nothing else ships in the vercel package.
//
// This shim defers loading the real module until the compile cache is enabled.
// https://nodejs.org/api/module.html#moduleenablecompilecachecachedir
// enableCompileCache was added in Node.js 22.8.0, so we need to handle older versions.
const entryAt = performance.now();
Reflect.set(globalThis, Symbol.for('vercel.cli.entry-at'), entryAt);
const startupTimings = process.env.VERCEL_TELEMETRY_DISABLED
  ? undefined
  : {
      marks: [
        {
          phase: 'compile_cache',
          timestamp: Number(process.hrtime.bigint() / BigInt(1000)),
        },
      ],
    };
Reflect.set(
  globalThis,
  Symbol.for('vercel.cli.startup-timings'),
  startupTimings
);
function markStartup(phase) {
  startupTimings?.marks.push({
    phase,
    timestamp: Number(process.hrtime.bigint() / BigInt(1000)),
  });
}
try {
  const { enableCompileCache } = await import('node:module');
  if (enableCompileCache) {
    enableCompileCache();
  }
} catch {}
markStartup('launcher');

// Run the one package this platform maps to: the native binary on macOS, Linux
// and Windows x64/arm64 (downloaded once into the CLI cache when the install
// skipped it), @vercel/cli-support everywhere else. Where a native binary
// should run, @vercel/cli-support (a dependency of vercel, so on every
// platform for now) is only a fallback, recorded in telemetry.
import { spawnSync } from 'node:child_process';
import {
  accessSync,
  constants as fsConstants,
  existsSync,
  mkdirSync,
  readFileSync,
  statSync,
  writeFileSync,
} from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, join, resolve, sep } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));

// At most one launcher warning per run.
let warnedThisRun = false;

// Keep in sync with packages/vc-native/scripts/platforms.mjs.
const NATIVE_TARGETS = [
  'darwin-arm64',
  'darwin-x64',
  'linux-arm64',
  'linux-arm64-musl',
  'linux-x64',
  'linux-x64-musl',
  'win32-arm64',
  'win32-x64',
];

function isWindowsTarget(target) {
  return target.startsWith('win32-');
}

function binaryName(target) {
  return isWindowsTarget(target) ? 'vercel.exe' : 'vercel';
}

// musl's `ldd` names itself. npm and pnpm skip the other libc's package via
// its `libc` field, but Yarn classic installs both, so the launcher must pick
// one.
// Detected the way npm does (npm-install-checks), so the launcher picks the
// package npm installed: the ldd script names its libc, and Node's report
// covers systems without ldd, such as minimal container images.
let musl;
function isMusl() {
  if (musl !== undefined) return musl;
  try {
    const ldd = readFileSync('/usr/bin/ldd', 'utf8');
    if (ldd.includes('musl')) return (musl = true);
    if (ldd.includes('GNU C Library')) return (musl = false);
  } catch {}
  try {
    const excludeNetwork = process.report.excludeNetwork;
    process.report.excludeNetwork = true;
    const report = process.report.getReport();
    process.report.excludeNetwork = excludeNetwork;
    musl =
      !report.header?.glibcVersionRuntime &&
      Array.isArray(report.sharedObjects) &&
      report.sharedObjects.some(
        file => file.includes('libc.musl-') || file.includes('ld-musl-')
      );
  } catch {
    musl = false;
  }
  return musl;
}

function platformTarget() {
  const target = `${process.platform}-${process.arch}`;
  return process.platform === 'linux' && isMusl() ? `${target}-musl` : target;
}

// Walk up from this install's own tree. `require.resolve()` is not used
// because it falls back to NODE_PATH and the global folders even when `paths`
// is given.
function findPackage(name) {
  let dir = __dirname;
  while (true) {
    const pkgDir = join(dir, 'node_modules', name);
    if (existsSync(join(pkgDir, 'package.json'))) return pkgDir;
    const parent = dirname(dir);
    if (parent === dir) return null;
    dir = parent;
  }
}

// The package this platform maps to: a native target or `cli-support`.
function mappedTarget() {
  const target = platformTarget();
  return NATIVE_TARGETS.includes(target) ? target : 'cli-support';
}

// Operating systems with native binaries. Where @vercel/cli-support runs on one
// of them, it stands in for a native binary, so it counts as a fallback.
const NATIVE_OSES = ['darwin', 'linux', 'win32'];

// Like the native package, a copy found for another vercel version (hoisted
// for another vercel in the same tree) counts as missing.
function findCliSupportEntry() {
  const found = findPackage('@vercel/cli-support');
  const pkgDir =
    (found && isOwnVersion(found) && found) ||
    resolvePackageWithoutNodeModules('@vercel/cli-support');
  const entry = pkgDir && join(pkgDir, 'dist', 'vc.js');
  return entry && existsSync(entry) ? entry : undefined;
}

// Where there's no node_modules folder to walk, resolve the package the way
// Node does, at this launcher's own version only: under Yarn Plug'n'Play,
// through its runtime (its paths still have a node_modules segment, inside the
// zip cache and .yarn/unplugged), and in Deno installs. Never otherwise inside
// a node_modules folder, where require.resolve() would also search NODE_PATH
// and the global folders.
function resolvePackageWithoutNodeModules(name) {
  if (!process.versions.pnp && __dirname.split(sep).includes('node_modules')) {
    return null;
  }
  try {
    const pkgDir = dirname(
      createRequire(import.meta.url).resolve(`${name}/package.json`)
    );
    return isOwnVersion(pkgDir, { strict: true }) ? pkgDir : null;
  } catch {
    return null;
  }
}

// Without a usable native package, `missing` says why, for telemetry: none
// found (`not_found`), one for another vercel version (`other_version`), or
// one without its binary (`no_binary`, such as antivirus removing it).
function resolveTarget() {
  const target = mappedTarget();
  if (target === 'cli-support') return { target };
  const pkgDir = findPackage(`@vercel/vc-native-${target}`);
  if (!pkgDir) return { target, missing: 'not_found' };
  if (!isOwnVersion(pkgDir)) return { target, missing: 'other_version' };
  const name = binaryName(target);
  const bin = [join(pkgDir, 'bin', name), join(pkgDir, name)].find(existsSync);
  return bin ? { target, bin } : { target, missing: 'no_binary' };
}
// Where this vercel is installed, for telemetry on fallbacks: an npx, pnpm dlx
// or bunx cache, a project's node_modules, or a global install. Only the
// bucket is sent, never the path. __dirname is the real path, so a pnpm
// install's `.pnpm` store still counts as its project.
function installKind() {
  const parts = __dirname.split(sep);
  if (parts.includes('_npx')) return 'npx';
  if (parts.some(part => part.startsWith('bunx-'))) return 'bunx';
  if (parts.includes('dlx')) return 'pnpm_dlx';
  const nodeModules = parts.indexOf('node_modules');
  if (nodeModules === -1) return undefined;
  const root = parts.slice(0, nodeModules);
  // pnpm (`pnpm/global/5`) and Yarn (`yarn/global`, `Yarn\Data\global` on
  // Windows) keep a package.json in their global folders; npm's global prefix
  // (`lib`, or `npm` on Windows) has none. A project folder named `global`
  // still counts as a project.
  const isPnpmGlobal =
    /^\d+$/.test(root.at(-1) ?? '') &&
    root.at(-2) === 'global' &&
    /pnpm/i.test(root.at(-3) ?? '');
  const isYarnGlobal =
    root.at(-1) === 'global' &&
    root.slice(-3, -1).some(part => /yarn/i.test(part));
  if (isPnpmGlobal || isYarnGlobal) return 'global';
  const rootDir = root.join(sep) || sep;
  return existsSync(join(rootDir, 'package.json')) ? 'project' : 'global';
}

// The Node.js major version, such as `22`.
function nodeMajor() {
  return process.versions.node.split('.')[0];
}

// The lookup walks up through parent node_modules, so it can reach a package
// hoisted for another `vercel` in the same tree. Treat a different version as
// missing, so the launcher downloads this version instead of running another.
// Unreadable versions don't block: the optional dependency pins it exactly.
// With `strict`, for packages found outside node_modules, they do.
function isOwnVersion(pkgDir, { strict = false } = {}) {
  const own = readOwnPackage()?.version;
  try {
    const found = JSON.parse(
      readFileSync(join(pkgDir, 'package.json'), 'utf8')
    ).version;
    if (typeof own !== 'string' || typeof found !== 'string') return !strict;
    return found === own;
  } catch {
    return !strict;
  }
}

// The package this launcher belongs to: `vercel`.
let ownPackage;
function readOwnPackage() {
  if (ownPackage === undefined) {
    try {
      ownPackage = JSON.parse(
        readFileSync(join(__dirname, '..', 'package.json'))
      );
    } catch {
      ownPackage = null;
    }
  }
  return ownPackage;
}

// Flags that make stdout a JSON document, so stderr must stay quiet.
function wantsJsonOutput(argv) {
  const formatIndex = argv.indexOf('--format');
  return (
    argv.some(arg => arg === '--json' || arg === '--format=json') ||
    (formatIndex !== -1 && argv[formatIndex + 1] === 'json')
  );
}

// When the native package is missing (an install that skipped optional
// dependencies, or one made before npm had the package), download the binary
// for this exact version into the CLI cache, once. Each version has its own
// directory, so a binary is written once and never replaced.
//
// After a failed attempt, wait before trying again: 15 minutes after the
// first failure, 2 hours after the second, then a day. The `download-failed`
// marker holds the number of failures; its age is the time since the last.
const DOWNLOAD_RETRY_AFTER = [
  { ms: 15 * 60 * 1000, label: '15 minutes' },
  { ms: 2 * 60 * 60 * 1000, label: '2 hours' },
  { ms: 24 * 60 * 60 * 1000, label: '24 hours' },
];

function retryAfter(failures) {
  return DOWNLOAD_RETRY_AFTER[
    Math.min(Math.max(failures, 1), DOWNLOAD_RETRY_AFTER.length) - 1
  ];
}

/** The failures recorded in the marker, and when the last one happened. */
function readFailedStamp(stamp) {
  try {
    const { mtimeMs } = statSync(stamp);
    // Earlier releases wrote an empty marker: one failure.
    const count = Number.parseInt(readFileSync(stamp, 'utf8'), 10);
    return { at: mtimeMs, count: count > 0 ? count : 1 };
  } catch {
    return undefined;
  }
}

// Where this version's binary is cached, or the fallback reason when there's
// nowhere to put it.
async function nativeCacheDir(target) {
  const version = readOwnPackage()?.version;
  if (
    typeof version !== 'string' ||
    !/^\d+\.\d+\.\d+(?:-[\w.-]+)?(?:\+[\w.-]+)?$/.test(version)
  ) {
    return { reason: 'target_missing' };
  }
  // Reported apart from target_missing, with which step failed: loading the
  // launcher's own launcher-paths.js (`import`, an incomplete package), or
  // resolving the directory (`path`), which throws on Windows when
  // LOCALAPPDATA is unset and os.homedir() throws.
  let config;
  try {
    config = await import('./launcher-paths.js');
  } catch {
    return { reason: 'cache_unresolved', cacheError: 'import' };
  }
  try {
    return {
      version,
      dir: join(config.getCachePath(), 'native', version, target),
    };
  } catch {
    return { reason: 'cache_unresolved', cacheError: 'path' };
  }
}

async function fetchNativeBinary(target) {
  // Only an installed package uses the download. A repository checkout
  // (packages/cli/dist/vc.js in this repository) runs the workspace's JS CLI,
  // so local changes and tests never run a published binary instead. Deno
  // installs have no node_modules either.
  if (!__dirname.split(sep).includes('node_modules')) {
    return { reason: 'not_in_node_modules' };
  }
  const cache = await nativeCacheDir(target);
  if (cache.reason) {
    return { reason: cache.reason, cacheError: cache.cacheError };
  }
  const bin = join(cache.dir, binaryName(target));
  if (existsSync(bin)) return { bin, source: 'cache' };

  // Tests only: never reach the real registry.
  if (process.env.__VERCEL_NATIVE_DOWNLOAD === '0') {
    return { reason: 'target_missing' };
  }
  // Without a writable cache the binary has nowhere to go and a failure can't
  // be recorded, so don't try: the JS CLI runs with the once-a-day warning.
  // Reported apart from target_missing: a sandbox that blocks writes to the
  // cache directory looks like this.
  try {
    mkdirSync(cache.dir, { recursive: true });
    accessSync(cache.dir, fsConstants.W_OK);
  } catch {
    return { reason: 'cache_unwritable', cacheDir: cache.dir };
  }
  // The wait only makes sense while the JS CLI can run the command meanwhile.
  // Without it, every run tries again.
  const failedStamp = join(cache.dir, 'download-failed');
  const previous = readFailedStamp(failedStamp);
  if (
    jsCliAvailable &&
    previous &&
    Date.now() - previous.at < retryAfter(previous.count).ms
  ) {
    return { reason: 'download_failed' };
  }

  const quiet = wantsJsonOutput(process.argv.slice(2));
  // A failed attempt shows in the JS CLI's trace as its own startup span.
  markStartup('native_download');
  try {
    const { downloadNativeBinary } = await import('./native-download.js');
    const downloaded = await downloadNativeBinary({
      target,
      version: cache.version,
      directory: cache.dir,
      log: quiet ? undefined : line => console.error(line),
      retryTimeouts: jsCliAvailable,
    });
    return {
      bin: downloaded.bin,
      source: 'download',
      attempts: downloaded.attempts,
    };
  } catch (error) {
    markStartup('launcher');
    const failures = (previous?.count ?? 0) + 1;
    try {
      writeFileSync(failedStamp, String(failures));
    } catch {}
    const known = error?.name === 'NativeDownloadError';
    const detail = known ? error.detail : 'unexpected error';
    // Without the JS CLI, the launcher reports this as an error instead.
    if (!quiet && jsCliAvailable) {
      console.error(
        `! Couldn't download the Vercel CLI binary (${detail}), so Node.js is running this command. The CLI tries again in ${retryAfter(failures).label}.\n${feedbackHint()}`
      );
      warnedThisRun = true;
    }
    // Only a run that tried reports why, so telemetry can tell attempts from
    // the runs that skip downloading while they wait.
    return {
      reason: 'download_failed',
      detail,
      kind: known ? error.kind : 'other',
      timeout: known ? error.timeout : undefined,
      progress: known ? error.progress : undefined,
      downloadFailure: {
        downloadError: known ? error.kind : 'other',
        downloadAttempts: String(known ? error.attempts : 1),
        downloadFailures: failures >= 3 ? '3_or_more' : String(failures),
        ...(known && error.phase && { downloadPhase: error.phase }),
        ...(known && error.code && { downloadCode: error.code }),
        ...(known && error.timeout && { downloadTimeout: error.timeout }),
        ...(known && error.progress && { downloadProgress: error.progress }),
        ...(known &&
          error.environment && {
            downloadProxy: error.environment.proxy ? 'true' : 'false',
            npmRegistry: error.environment.npmRegistry,
            npmProxy: error.environment.npmProxy ? 'true' : 'false',
            npmTls: error.environment.npmTls ? 'true' : 'false',
          }),
      },
    };
  }
}

// Where a native binary exists it always runs: an opt-out
// (VERCEL_CLI_USE_NATIVE_BINARY, then a persisted `useNativeBinary`
// preference) is only found to say it no longer applies. Returns where the
// opt-out came from (`env` or `config`), or false. Any failure to read config
// counts as no preference.
async function nativeBinaryOptOut() {
  const envOverride = process.env.VERCEL_CLI_USE_NATIVE_BINARY;
  if (envOverride === '0' || envOverride === 'false') return 'env';
  if (envOverride === '1' || envOverride === 'true') return false;
  try {
    const config = await import('./launcher-paths.js');
    const argDir = globalConfigDirFromArgv();
    const configDir = argDir
      ? resolve(process.cwd(), argDir)
      : config.getGlobalPathConfig();
    return config.readGlobalConfigFlag(
      config.getConfigFilePath(configDir),
      'useNativeBinary'
    ) === false
      ? 'config'
      : false;
  } catch {
    return false;
  }
}

// Ctrl+C (and Ctrl+Break on Windows) also reach the binary, which handles
// them. The launcher waits for it instead of exiting: on Windows, Node.js
// exiting would also kill the binary before it could clean up.
const CONSOLE_SIGNALS =
  process.platform === 'win32' ? ['SIGINT', 'SIGBREAK'] : ['SIGINT'];
function waitForNative() {}

function optOutSetting(source) {
  return source === 'env'
    ? `VERCEL_CLI_USE_NATIVE_BINARY=${process.env.VERCEL_CLI_USE_NATIVE_BINARY}`
    : '"useNativeBinary": false in the Vercel CLI config';
}

// Agents can be told to report what they run into, so every JS CLI fallback
// warning ends with the vercel feedback command on its own line, like other
// recovery commands. It doesn't prescribe a note: <DESCRIPTION> is for whoever
// reads it to describe what they're seeing.
const FALLBACK_FEEDBACK =
  "A future release of vercel removes this fallback. If this keeps happening, describe what you're seeing with:";

function feedbackHint(lead = FALLBACK_FEEDBACK) {
  return `  ${lead}\n    vercel feedback "<DESCRIPTION>"`;
}

// A warning about the JS CLI fallback, at most once a day. Agents often run
// non-interactively and need to see it; only --json skips it.
async function warnOncePerDay(stampName, message) {
  if (warnedThisRun) return;
  if (wantsJsonOutput(process.argv.slice(2))) return;
  const dir = await stampDirectory();
  const stamp = dir && join(dir, stampName);
  try {
    if (stamp && Date.now() - statSync(stamp).mtimeMs < DAY_MS) return;
  } catch {}
  console.error(message);
  warnedThisRun = true;
  if (stamp) {
    try {
      writeFileSync(stamp, '');
    } catch {}
  }
}

// Where once-a-day stamps go: the global config directory, created if it's
// missing (as on a fresh CI machine), else the CLI's cache directory. Both are
// under the user's home, never a shared directory such as the system temp
// directory, where another user could plant a symlink for the stamp write to
// follow. With neither writable (a sandbox blocking writes to home), there is
// no stamp and the warning shows on every run.
async function stampDirectory() {
  let config;
  try {
    config = await import('./launcher-paths.js');
  } catch {
    return undefined;
  }
  const argDir = globalConfigDirFromArgv();
  const candidates = [
    () =>
      argDir ? resolve(process.cwd(), argDir) : config.getGlobalPathConfig(),
    () => config.getCachePath(),
  ];
  for (const candidate of candidates) {
    try {
      const dir = candidate();
      mkdirSync(dir, { recursive: true });
      accessSync(dir, fsConstants.W_OK);
      return dir;
    } catch {}
  }
  return undefined;
}

const DAY_MS = 24 * 60 * 60 * 1000;

// The JS CLI's entry point in @vercel/cli-support, the fallback when the native
// binary can't run. Without it, every fallback below becomes an error with a
// fix instead, so making @vercel/cli-support an optional dependency for other
// operating systems only needs no launcher change.
const cliSupportEntry = findCliSupportEntry();
const jsCliAvailable = Boolean(cliSupportEntry);

// Read by the JS CLI (src/index.ts) and reported in telemetry. Inside the
// native binary, pkg.js sets it to `native` instead; this file never runs
// there.
const LAUNCH = Symbol.for('vercel.cli.launch');
let launch;
// Why the JS CLI would run, for the warning or, without it, the error.
let fallback;
if (process.env.VERCEL_VC_NATIVE === '1' && jsCliAvailable) {
  // A process the native binary spawned (a build script, a dev command)
  // inherited VERCEL_VC_NATIVE=1 and runs the JS CLI. Without the JS CLI, it
  // resolves and runs the binary like any launch.
  launch = {
    runtime: 'cli-support',
    target: mappedTarget(),
    reason: 'inherited_native_env',
  };
} else {
  const resolved = resolveTarget();
  let missingReason = 'target_missing';
  let downloadFailure;
  const nativeTarget = resolved.target !== 'cli-support';
  if (nativeTarget) {
    const optOut = await nativeBinaryOptOut();
    if (optOut) {
      await warnOncePerDay(
        '.native-opt-out-warned',
        `! ${optOutSetting(optOut)} no longer applies: this version of vercel only runs the native binary.`
      );
    }
  }
  if (!resolved.bin && nativeTarget) {
    const fetched = await fetchNativeBinary(resolved.target);
    resolved.bin = fetched.bin;
    resolved.source = fetched.source;
    resolved.attempts = fetched.attempts;
    missingReason = fetched.reason ?? missingReason;
    downloadFailure = fetched.downloadFailure;
    fallback = fetched;
  }
  if (resolved.bin) {
    // Internal worker arguments intentionally trampoline too. The packaged
    // native binary sets VERCEL_VC_NATIVE=1 in pkg.js and enters the JS CLI
    // (src/vc.js), which handles the request.
    for (const signal of CONSOLE_SIGNALS) process.on(signal, waitForNative);
    const r = spawnSync(resolved.bin, process.argv.slice(2), {
      stdio: 'inherit',
      windowsHide: true,
      env: {
        ...process.env,
        VERCEL_VC_NATIVE: '1',
        // Upgrades belong to the vercel package, not its native runtime
        // dependency. Always replace an inherited value with this launcher's
        // own entrypoint.
        VERCEL_CLI_PACKAGE_ENTRYPOINT: fileURLToPath(import.meta.url),
        VERCEL_CLI_PACKAGE_EXECUTABLE: resolved.bin,
        // Reported in telemetry. pkg.js reads it and removes it, so the
        // binary's child processes don't inherit it.
        ...(resolved.source && {
          __VERCEL_CLI_NATIVE_SOURCE: resolved.source,
        }),
        ...(resolved.attempts && {
          __VERCEL_CLI_NATIVE_DOWNLOAD_ATTEMPTS: String(resolved.attempts),
        }),
      },
    });
    // Restores the default handling, so re-raising a signal below terminates
    // this process, and the JS CLI installs its own handlers if it runs.
    for (const signal of CONSOLE_SIGNALS) process.off(signal, waitForNative);
    // Fall back only when the binary never started, so no command code has
    // run. spawnSync sets no timeout or output buffer here, so any error means
    // that, such as ENOENT, EACCES or ENOEXEC, or EPERM, EFTYPE or UNKNOWN when
    // Windows blocks the binary (AppLocker, WDAC, Smart App Control,
    // antivirus). Never fall back on an exit status: a loader failure (e.g.
    // glibc mismatch) and a command's own failure are indistinguishable, and
    // retrying a command in Node.js could repeat remote mutations.
    if (!r.error) {
      if (r.signal) {
        try {
          process.kill(process.pid, r.signal);
        } catch {}
      }
      process.exit(r.status ?? 1);
    }
    launch = {
      runtime: 'cli-support',
      target: resolved.target,
      reason: r.error.code ?? 'UNKNOWN',
      // Set when the binary came from the cache or a download instead.
      ...(resolved.missing && { nativePackage: resolved.missing }),
      install: installKind(),
      nodeMajor: nodeMajor(),
    };
    // `bin` marks a spawn failure, whatever its error code.
    fallback = { bin: resolved.bin };
  } else if (nativeTarget || NATIVE_OSES.includes(process.platform)) {
    // The JS CLI stands in for a native binary: one that couldn't be
    // installed, downloaded or started, or a CPU without one (such as
    // linux-ia32) on an OS that has them.
    launch = {
      runtime: 'cli-support',
      target: resolved.target,
      reason: missingReason,
      ...(resolved.missing && { nativePackage: resolved.missing }),
      ...(fallback?.cacheError && { cacheError: fallback.cacheError }),
      install: installKind(),
      nodeMajor: nodeMajor(),
      ...downloadFailure,
    };
  } else {
    // FreeBSD and every other OS without native binaries: the JS CLI is the
    // package this platform maps to, not a fallback.
    launch = { runtime: 'cli-support' };
  }
}

// Without the JS CLI, nothing can run the command: report why and how to fix
// it, before loading anything else.
if (!jsCliAvailable) {
  let reportLauncherFailure;
  try {
    ({ reportLauncherFailure } = await import('./launcher-errors.js'));
  } catch {
    // An incomplete package: still fail with the reason and the fix.
    console.error(
      `✗ Couldn't start Vercel CLI (${launch.reason ?? 'target_missing'}). Reinstall vercel with the package manager that installed it.`
    );
    process.exit(1);
  }
  process.exit(
    reportLauncherFailure({
      reason: launch.reason ?? 'target_missing',
      target: launch.target ?? 'cli-support',
      platform: platformTarget(),
      version: readOwnPackage()?.version,
      detail: fallback?.detail,
      kind: fallback?.kind,
      timeout: fallback?.timeout,
      progress: fallback?.progress,
      cacheDir: fallback?.cacheDir,
      cacheError: fallback?.cacheError,
      bin: fallback?.bin,
      json: wantsJsonOutput(process.argv.slice(2)),
    })
  );
}

globalThis[LAUNCH] = launch;

// While it ships on these platforms, the JS CLI fallback warns once a day that
// it's going away, with the fix and the command to report it. A fresh download
// failure already warned, and warnDeprecatedArch() covers Linux architectures
// without a native binary.
if (launch.reason) {
  const reinstall = 'Reinstall vercel without omitting optional dependencies.';
  const deprecatedArch =
    process.platform === 'linux' && !['x64', 'arm64'].includes(process.arch);
  const platform = platformTarget();
  let message;
  if (launch.reason === 'target_missing' && launch.target !== 'cli-support') {
    const pkg = `@vercel/vc-native-${launch.target}`;
    message = `! ${pkg} isn't installed, so Node.js is running this command. ${reinstall}\n${feedbackHint()}`;
  } else if (launch.reason === 'target_missing' && !deprecatedArch) {
    message = `! Vercel CLI has no native binary for ${platform}, so Node.js is running this command.\n${feedbackHint(
      'A future release of vercel removes this fallback. If you need Vercel CLI on this platform, tell us with:'
    )}`;
  } else if (launch.reason === 'download_failed') {
    message = `! The Vercel CLI binary for ${launch.target} couldn't be downloaded, so Node.js is running this command. Allow access to registry.npmjs.org, or ${reinstall.charAt(0).toLowerCase()}${reinstall.slice(1)}\n${feedbackHint()}`;
  } else if (launch.reason === 'cache_unwritable') {
    message = `! The Vercel CLI binary for ${launch.target} can't be downloaded because ${fallback?.cacheDir ?? 'the cache directory'} isn't writable, so Node.js is running this command. Make it writable, or set XDG_CACHE_HOME to a writable directory.\n${feedbackHint()}`;
  } else if (
    launch.reason === 'cache_unresolved' &&
    launch.cacheError === 'import'
  ) {
    // An incomplete package: only reinstalling restores launcher-paths.js.
    message = `! The Vercel CLI binary for ${launch.target} can't be downloaded because the vercel package is incomplete, so Node.js is running this command. ${reinstall}\n${feedbackHint()}`;
  } else if (launch.reason === 'cache_unresolved') {
    message = `! The Vercel CLI binary for ${launch.target} can't be downloaded because the CLI couldn't find its cache directory, so Node.js is running this command. Set XDG_CACHE_HOME to a writable directory, or ${reinstall.charAt(0).toLowerCase()}${reinstall.slice(1)}\n${feedbackHint()}`;
  } else if (fallback?.bin) {
    message = `! The native Vercel CLI binary could not start (${launch.reason}), so Node.js is running this command. ${reinstall}\n${feedbackHint()}`;
  }
  if (message) await warnOncePerDay('.js-fallback-warned', message);
}

// Read `--global-config`/`-Q` without loading the full CLI arg parser.
function globalConfigDirFromArgv() {
  const argv = process.argv.slice(2);
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === '--global-config' || arg === '-Q') {
      return argv[i + 1];
    }
    if (arg.startsWith('--global-config=')) {
      return arg.slice('--global-config='.length);
    }
  }
  return undefined;
}

// Linux on anything but x64/arm64 has no native binary, and will lose the JS
// CLI from `vercel` itself in a future release.
async function warnDeprecatedArch() {
  if (
    process.platform !== 'linux' ||
    ['x64', 'arm64'].includes(process.arch) ||
    process.env.VERCEL_VC_NATIVE === '1'
  ) {
    return;
  }
  // Agents often run non-interactively and need to see it; only --json skips it.
  if (wantsJsonOutput(process.argv.slice(2))) return;
  let stamp;
  try {
    const config = await import('./launcher-paths.js');
    const argDir = globalConfigDirFromArgv();
    const configDir = argDir
      ? resolve(process.cwd(), argDir)
      : config.getGlobalPathConfig();
    if (existsSync(configDir)) {
      stamp = join(configDir, '.arch-deprecation-warned');
      if (Date.now() - statSync(stamp).mtimeMs < 24 * 60 * 60 * 1000) return;
    }
  } catch {}
  const target = `${process.platform}-${process.arch}`;
  console.error(
    `! Support for ${target} will be removed from the vercel package in a future release.\n${feedbackHint('If you still need it, tell us with:')}`
  );
  if (stamp) {
    try {
      writeFileSync(stamp, '');
    } catch {}
  }
}

await warnDeprecatedArch();

// The JS CLI handles everything else: --version and --help fast paths, the
// internal build worker, and argument errors during initialization.
await import(pathToFileURL(cliSupportEntry).href);
